import{_ as t,o as i,c as r,a3 as o}from"./chunks/framework.BlfGB29P.js";const p=JSON.parse('{"title":"Disable entity picture image overrides","description":"Learn how to disable entity picture image overrides and when to use this performance option","frontmatter":{"title":"Disable entity picture image overrides","description":"Learn how to disable entity picture image overrides and when to use this performance option"},"headers":[],"relativePath":"en/projects/uix/extras/disable-entity-picture-image-override.md","filePath":"en/projects/uix/extras/disable-entity-picture-image-override.md","lastUpdated":1793198184000}'),a={name:"en/projects/uix/extras/disable-entity-picture-image-override.md"};function n(s,e,d,c,l,g){return i(),r("div",null,[...e[0]||(e[0]=[o('<blockquote><p>Adapted from the canonical English UIX documentation by <a href="https://github.com/Lint-Free-Technology/uix" target="_blank" rel="noreferrer">Lint-Free-Technology/uix</a>, <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noreferrer">CC BY 4.0</a>. Source: <code>dev</code> / <strong>9.0.0-beta.2</strong>, revision <a href="https://github.com/Lint-Free-Technology/uix/commit/26e54e6d4973231a393933e6479ed1b03cc86cd3" target="_blank" rel="noreferrer">26e54e6</a>, reviewed 22 October 2026. This source mirror may describe preview behavior beyond stable 8.4.0. Markup adapted for this site; the <a href="https://uix.lf.technology/" target="_blank" rel="noreferrer">original documentation</a> remains authoritative.</p></blockquote><h1 id="disable-entity-picture-image-overrides" tabindex="-1">Disable entity picture image overrides <a class="header-anchor" href="#disable-entity-picture-image-overrides" aria-label="Permalink to &quot;Disable entity picture image overrides&quot;">​</a></h1><p>By default, UIX patches standard Home Assistant badge and marker elements (<code>ha-entity-marker</code>, <code>ha-tile-icon</code>, <code>state-badge</code>, <code>ha-user-badge</code>, <code>ha-person-badge</code>) to allow custom entity picture image overrides (such as <code>--uix-image</code> or <code>--uix-image-for-&lt;entity_id&gt;</code>). UIX provides an option to disable this patching behavior to improve rendering performance and reduce CPU overhead on low-power devices.</p><h2 id="setting-via-the-integration-ui" tabindex="-1">Setting via the integration UI <a class="header-anchor" href="#setting-via-the-integration-ui" aria-label="Permalink to &quot;Setting via the integration UI&quot;">​</a></h2><p>The option is <strong>unset by default</strong>. To set the option:</p><ol><li>In Home Assistant, go to <strong>Settings → Devices &amp; Services → UI eXtension → Configure</strong>.</li><li>Select <strong>Performance settings</strong> from the menu.</li><li>Toggle <strong>Disable entity picture image overrides</strong> on.</li><li>Save.</li></ol><p>The setting takes effect immediately across all connected browser sessions — no page reload required.</p><h2 id="behavior-when-set" tabindex="-1">Behavior when set <a class="header-anchor" href="#behavior-when-set" aria-label="Permalink to &quot;Behavior when set&quot;">​</a></h2><p>When this option is set:</p><ul><li>Standard Home Assistant badge and marker elements are <strong>not patched</strong> or monitored for custom image properties.</li><li>Existing custom entity picture image overrides via CSS variables (e.g. <code>--uix-image</code>, <code>--uix-image-for-*</code>) will <strong>not</strong> be applied to badge or marker elements.</li></ul>',10)])])}const m=t(a,[["render",n]]);export{p as __pageData,m as default};
